import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter290 {
    var current: Int by Delegates.observable(91) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome291 {
    data class Success(val payload: String) : Outcome291()
    data object Failure : Outcome291()
}

fun describe291(outcome: Outcome291): String = when (outcome) {
    is Outcome291.Success -> outcome.payload
    Outcome291.Failure -> "failed"
}
@JvmName("step292")
fun step292(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 8
}
